package example;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.*;
class AimControlCombatTest {
 GameSession game;Player player;List<String> messages=new ArrayList<>();ObjectMapper json=new ObjectMapper();
 @BeforeEach void setup(){game=new GameSession(new GameEventSink(){public void broadcast(String m){messages.add(m);}public void send(Player p,String m){}});player=game.connectPlayer("aim-test");game.setRoomOwner(player);game.handleMessage(player,"START:DEBUG");game.players.forEach(p->p.human=true);game.enemies.clear();game.trapSlots.clear();game.unlockedAreas.addAll(GameMap.AREAS.stream().map(UnlockArea::id).toList());player.x=1020;player.y=1900;messages.clear();CombatTestRandom.use(game,()->.5);}
 void equip(String id){player.weapons.setOwned(id,true);player.weapons.setAmmo(id,20);player.equipWeapon(id);player.cooldown=0;player.firing=false;}
 void fire(String suffix){game.handleMessage(player,"FIRE:"+(player.x+200)+":"+player.y+":1:0"+suffix);}
 @Test void lookUsesServerTime(){game.handleMessage(player,"LOOK:0:-1:0");game.update(.05);game.handleMessage(player,"LOOK:1:0:0");assertEquals(1.5,player.aimControl.turn);for(int i=0;i<100;i++)game.handleMessage(player,"LOOK:1:0:0");assertEquals(1.5,player.aimControl.turn);}
 @Test void fireChecksDirectionWithoutLookPackets(){equip("pistol");game.handleMessage(player,"LOOK:0:-1:0");fire("");assertEquals(1.5,player.aimControl.turn);}
 @Test void invalidDisplayedTimeDoesNotSpendAmmo(){equip("rifle");fire(":10");assertEquals(20,player.weapons.ammo("rifle"));assertFalse(player.firing);fire(":NaN");assertEquals(20,player.weapons.ammo("rifle"));fire(":0");assertEquals(19,player.weapons.ammo("rifle"));}
 @Test void secondaryHasSameValidation(){player.job="attacker";player.weapons.grant("rifle");player.secondaryWeapon="rifle";player.weapons.setAmmo("rifle",20);game.handleMessage(player,"LOOK:0:-1:0");game.handleMessage(player,"SECONDARY_FIRE:1220:1900:1:0:100");assertEquals(20,player.weapons.ammo("rifle"));game.handleMessage(player,"SECONDARY_FIRE:1220:1900:1:0:0");assertEquals(19,player.weapons.ammo("rifle"));assertEquals(1.5,player.aimControl.turn);}
 @Test void actualMovementStoppingAndJumpAreMeasured(){player.moveX=1;game.update(.1);assertTrue(player.aimControl.speedRatio>.5);player.moveX=0;game.update(.1);assertEquals(0,player.aimControl.speedRatio);double peak=player.aimControl.movement;game.update(.5);assertTrue(player.aimControl.movement<peak*.2);game.handleMessage(player,"JUMP");game.update(.05);assertTrue(player.aimControl.airborne);}
 @Test void coneActuallyControlsBulletAndAmmo()throws Exception{equip("rifle");player.aimControl.elapsed=.7;player.aimControl.movement=1;player.aimControl.turn=.5;int[] n={0};CombatTestRandom.use(game,()->n[0]++%2==0?.81:.25);double radius=AimControlRules.radius(player.aimControl,"rifle",player.sniper);fire(":0.7");JsonNode trace=null;for(String m:messages){var e=json.readTree(m);if(e.path("effect").asText().equals("hit")&&e.path("damage").asDouble()==0)trace=e;}assertNotNull(trace);double dx=trace.path("x").asDouble()-trace.path("fromX").asDouble(),dz=trace.path("hitHeight").asDouble()-trace.path("fromHeight").asDouble();assertEquals(radius*SniperRules.PIXEL_SLOPE*.9,dz/dx,.002);assertEquals(19,player.weapons.ammo("rifle"));}
 @Test void cpuUsesSameCombatRule(){equip("rifle");player.human=false;player.aimControl.look(0,-1,0);game.combat.attackAt(player,player.x+200,player.y);assertEquals(1.5,player.aimControl.turn);assertEquals(19,player.weapons.ammo("rifle"));}
 @Test void snapshotPublishesServerState()throws Exception{player.aimControl.elapsed=3;player.aimControl.movement=.8;var snap=json.readTree(SnapshotBuilder.build(game));assertEquals(3,snap.path("players").get(0).path("aimControl").path("elapsed").asDouble());assertEquals(.8,snap.path("players").get(0).path("aimControl").path("movement").asDouble());assertTrue(snap.path("rules").path("weapons").path("rifle").path("aimControl").asBoolean());assertFalse(snap.path("rules").path("weapons").path("rocket").path("aimControl").asBoolean());}
 @Test void swappingCannotResetBreathOrPenalty(){equip("rifle");player.aimControl.elapsed=3;player.aimControl.turn=1;equip("pistol");assertEquals(3,player.aimControl.elapsed);assertEquals(1,player.aimControl.turn);}
 @Test void nonPlayingOrDownCannotSendLook(){game.phase=GamePhase.LOBBY;game.handleMessage(player,"LOOK:1:0:0");assertFalse(player.aimControl.hasLook);game.phase=GamePhase.PREPARING;player.down=true;game.handleMessage(player,"LOOK:1:0:0");assertFalse(player.aimControl.hasLook);}
}
